        d = [(-w[i]) for i in range(n)]
        d[s_idx] += 1.0
        gap = sum(grad[i] * (-d[i]) for i in range(n))  # = <grad, w - s>
        if gap <= 1e-12:
            break
        # d^T (G + ridge I) d
        gd = [0.0] * n
        for i in range(n):
            acc = 0.0
            row = gram[i]
            for j in range(n):
                if d[j]:
                    acc += row[j] * d[j]
            gd[i] = acc + ridge * d[i]
        denom = sum(d[i] * gd[i] for i in range(n))
        if denom <= 1e-18:
            break
        step = gap / denom
        if step > 1.0:
            step = 1.0
        if step <= 0.0:
            break
        for i in range(n):
            if d[i]:
                w[i] += step * d[i]
        if step < 1e-12:
            break
    total = sum(w)
    if total <= 0.0:
        return [1.0 / n] * n
    return [wi / total for wi in w]


def matching_mse(columns: list[list[float]], target: list[float], weights: list[float]) -> float:
    m = len(target)
    if m == 0:
        return float("inf")
    total = 0.0
    for k in range(m):
        approx = sum(weights[i] * columns[i][k] for i in range(len(columns)))
        total += (approx - target[k]) ** 2
    return total / m


